.section-testimonial {
  background-color: var(--bg-surface);
  position: relative;
}

.testimonial-card {
  background-color: var(--bg-app);
  border: 1px solid var(--card-border);
  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.04);
}

.testimonial-card p.fs-4 {
  color: var(--dark);
  font-family: var(--font-headings);
  line-height: 1.5;
  font-weight: 500;
}

/* Contact / Dark Hero Section */
.hero-dark {
  background-color: var(--dark);
  color: #ffffff;
  position: relative;
}

.hero-dark h2 {
  font-size: clamp(1.9rem, 4vw, 2.5rem);
}

/* Footer */
.app-footer {
  background-color: var(--dark-surface);
  color: #ffffff;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

/* Global Images & Badges */
img {
  max-width: 100%;
  height: auto;
}

.badge-theme {
  background-color: var(--primary);
  display: inline-block;
  padding: 6px 14px;
  border-radius: 20px;
  font-size: 0.85rem;
  color: #ffffff;
  font-weight: 600;
}

/* Responsive adjustments */
@media (max-width: 767.98px) {
  .hero-img,
  .about-img {
    height: 260px;
    max-width: 100%;
    margin-top: 0.5rem;
  }

  .card-service {
    min-height: auto;
    padding: 1.5rem !important;
  }

  .card-service h6 {
    min-height: auto;
  }

  .hero .btn-brand,
  .hero-dark .btn-brand {
    width: 100%;
  }
}

